import{focusState}from './senses-models.js?v=20261023-physicscomplete01';
export const st=(x,y,s,z=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${z}">${s}</text>`;
const line=(a,b,c='#aec9cc')=>`<path d="M${a}L${b}" stroke="${c}" stroke-width="2" fill="none"/>`;
export const sensesSVG=(body,label)=>`<svg viewBox="0 0 560 380" role="img" aria-label="${label}"><defs><radialGradient id="sensesSkin"><stop stop-color="#f0c1ae"/><stop offset="1" stop-color="#b77971"/></radialGradient><radialGradient id="sensesLens"><stop stop-color="#d9eeee"/><stop offset="1" stop-color="#83afb9"/></radialGradient></defs>${body}</svg>`;
export function sensesFigure({kind='eye',state='far',corrected=false,progress=0,pupilRadius,lensWidth,concealed=false}={}){
if(concealed)return sensesSVG(st(280,190,'Predict, then reveal the evidence',21),'Evidence concealed until prediction');
if(kind==='brain')return sensesSVG(`<path d="M135 210C75 174 91 106 146 84C160 41 228 36 266 60C310 31 393 52 414 105C455 131 443 190 411 209L278 232Z" fill="url(#sensesSkin)" stroke="${state==='cortex'?'#f4d59e':'#f1d7cb'}" stroke-width="${state==='cortex'?6:2}"/>${[0,1,2,3,4].map(i=>`<path d="M${135+i*51} 100q-28 30 7 52t-8 47" fill="none" stroke="#8e5d60" stroke-width="4"/>`).join('')}<ellipse cx="370" cy="232" rx="58" ry="41" fill="#a8c4c3" stroke="${state==='cerebellum'?'#f4d59e':'#e9eee7'}" stroke-width="4"/>${[0,1,2,3].map(i=>`<path d="M328 ${214+i*12}q40-12 82 0" fill="none" stroke="#5d8d97" stroke-width="3"/>`).join('')}<path d="M290 217Q318 240 304 291L283 305Q292 260 269 234Z" fill="#dbbc91" stroke="${state==='medulla'?'#f4d59e':'#f4e0bf'}" stroke-width="4"/>${line('192 80','124 33')+st(112,26,'Cerebral cortex')+line('399 235','460 274')+st(462,294,'Cerebellum')+line('298 274','226 312')+st(210,333,'Medulla')+st(280,365,'Side view · schematic regions and folds',14)}`,'Side view: cerebral cortex outside, cerebellum behind brainstem, medulla below');
if(kind==='evidence')return sensesSVG(`<rect x="75" y="85" width="410" height="210" rx="22" fill="#28465d" stroke="#9dbabf"/><circle cx="160" cy="168" r="40" fill="url(#sensesSkin)"/>${line('202 168','255 168')}<path d="M245 160l12 8-12 8" fill="none" stroke="#f0c3ad"/>${st(350,150,state==='mri'?'Internal image':state==='stimulation'?'Observed response':state==='damage'?'Changed function':'Compare alternatives',20)+st(280,252,'Evidence supports a reasoned conclusion',18)+st(280,330,'Methods and treatment choices have limitations',15)}`,'Compare the stated evidence and limitations; schematic rather than a clinical scan');
if(kind==='pupil'){let rad=pupilRadius??(state==='dim'?55:state==='bright'?22:22+33*Math.sin(progress*Math.PI)**2);return sensesSVG(`<circle cx="280" cy="180" r="115" fill="#e5ddd0"/><circle cx="280" cy="180" r="85" fill="#9ab5bb" stroke="#dce8e4" stroke-width="3"/>${Array.from({length:24},(_,i)=>{let a=i*Math.PI/12;return line(`${280+Math.cos(a)*65} ${180+Math.sin(a)*65}`,`${280+Math.cos(a)*82} ${180+Math.sin(a)*82}`,'#41677b')}).join('')}<circle cx="280" cy="180" r="${rad}" fill="#132a40"/>${st(280,326,state==='dim'?'Dim light · larger pupil':state==='bright'?'Bright light · smaller pupil':'Pupil controls light entry',19)}`,'Front view of iris and pupil; aperture changes light entry, not lens focusing');}
let mode=state==='near'?'near':'far',f=focusState(state,corrected),lw=lensWidth??f.lensWidth;let focus=f.focus;
let ray=(y)=>{let sign=y<190?-1:1,front=(kind==='accommodation'&&mode==='near'||state==='hyperopia')?190+sign*17:y,atLens=corrected?(state==='myopia'?y+sign*9:y-sign*9):y;return `<path d="M35 ${front}L98 ${y}L142 ${atLens}L220 ${atLens}L${focus} 190${state==='myopia'&&!corrected?`L430 ${190-sign*16}`:''}" stroke="#f0c39a" stroke-width="2.5" fill="none"/>`;};
let art=`<path d="M156 95C250 22 430 51 445 183C456 305 282 350 165 283Q119 191 156 95Z" fill="#34536b" stroke="#e5ded2" stroke-width="12"/><path d="M162 102C265 41 418 67 430 190C426 297 276 326 169 277" fill="none" stroke="#edaa93" stroke-width="5"/><path d="M156 95Q78 190 165 283" fill="#a2c7ce" fill-opacity=".3" stroke="#c4e3e5" stroke-width="5"/><path d="M181 112v47m0 62v49" stroke="#9ab8c3" stroke-width="10"/><ellipse cx="220" cy="190" rx="${lw}" ry="59" fill="url(#sensesLens)" stroke="#d4e9e7" stroke-width="2"/><path d="M208 115L197 145M232 115L241 145M208 265L197 235M232 265L241 235" stroke="#dfcba9" stroke-width="${mode==='near'?2:4}"/><ellipse cx="220" cy="109" rx="30" ry="9" fill="#bd8e91"/><ellipse cx="220" cy="271" rx="30" ry="9" fill="#bd8e91"/><path d="M440 210L502 237L493 256L434 233" fill="#c8b69d" stroke="#e8ddc9" stroke-width="3"/>`;
if(kind==='vision'||kind==='accommodation'){art+=ray(150)+ray(230)+line('430 105','430 275','#f4eee3')+`<circle cx="${focus}" cy="190" r="5" fill="#f8e0a5"/>`;if(corrected)art+=`<path d="M95 128Q${state==='myopia'?115:70} 190 95 252M101 128Q${state==='myopia'?81:126} 190 101 252" fill="#aacbd4" stroke="#dae8e4"/>`;art+=st(280,342,kind==='accommodation'?(mode==='near'?'Near · loose ligaments · thick lens':'Distant · tight ligaments · thin lens'):(corrected?'Corrected focus on retina':state==='myopia'?'Myopia · focus before retina':'Hyperopia · focus behind retina'),17)+st(280,369,'Schematic ray paths · not an optical measurement',13);}
else art+=line('334 78','365 28')+st(380,23,'Sclera')+line('392 110','464 77')+st(477,67,'Retina')+line('120 174','65 100')+st(60,87,'Cornea')+line('181 133','127 37')+st(108,25,'Iris')+line('220 190','275 335')+st(280,357,'Lens')+line('220 108','278 25')+st(276,17,'Ciliary muscle',13)+line('240 137','360 31')+st(412,35,'Ligaments',13)+st(476,288,'Optic nerve',14);
if((kind==='vision'||kind==='accommodation')&&progress>0){let x=35+(focus-35)*progress,y=x<220?150:150+40*(x-220)/(focus-220);art+=`<circle cx="${x}" cy="${y}" r="5" fill="#fff3cc"/>`;}return sensesSVG(art,'Eye cutaway: cornea and lens at front, retina at back, optic nerve leaves posterior; '+state+(corrected?' corrected':''));
}
export function sensesAssessmentFigure(f){if(f.diagram==='brain')return sensesFigure({kind:'brain'}).replace('Cerebral cortex','A').replace('Cerebellum','B').replace('Medulla','C').replace('Side view: cerebral cortex outside, cerebellum behind brainstem, medulla below','Side-view brain diagram with regions A, B and C');let svg=sensesFigure({kind:'vision',state:f.mode||'myopia'});return svg.replace(/<text[^>]*>Myopia[^<]*<\/text>/g,'').replace(/<text[^>]*>Hyperopia[^<]*<\/text>/g,'').replace('myopia','distant-object example').replace('hyperopia','near-object example')+'';}
